import{c as d,Q as r,j as a,m as o}from"./chunks/framework.B2dUnTNU.js";const c=JSON.parse('{"title":"B42 近战武器排名","description":"","frontmatter":{},"headers":[],"relativePath":"b42/weapons-tier.md","filePath":"b42/weapons-tier.md","lastUpdated":1779624442000}'),e={name:"b42/weapons-tier.md"};function n(s,t,h,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="b42-近战武器排名" tabindex="-1">B42 近战武器排名 <a class="header-anchor" href="#b42-近战武器排名" aria-label="Permalink to &quot;B42 近战武器排名&quot;">​</a></h1><p>基于 B42 新机制（肌肉疲劳、武器部件系统、锐利度、修理衰减）的全面排名。B41 老玩家注意——武器评价标准和 B41 <strong>完全不同</strong>了。</p><hr><h2 id="⚠️-b41-→-b42-武器系统变化" tabindex="-1">⚠️ B41 → B42 武器系统变化 <a class="header-anchor" href="#⚠️-b41-→-b42-武器系统变化" aria-label="Permalink to &quot;⚠️ B41 → B42 武器系统变化&quot;">​</a></h2><p>在排名之前，理解这些新机制至关重要：</p><h3 id="_1-肌肉疲劳" tabindex="-1">1. 肌肉疲劳 <a class="header-anchor" href="#_1-肌肉疲劳" aria-label="Permalink to &quot;1. 肌肉疲劳&quot;">​</a></h3><ul><li>武器越重，持续挥舞时间越短</li><li>轻型武器的价值从&quot;垃圾&quot;变成&quot;续航王&quot;</li></ul><h3 id="_2-武器部件系统" tabindex="-1">2. 武器部件系统 <a class="header-anchor" href="#_2-武器部件系统" aria-label="Permalink to &quot;2. 武器部件系统&quot;">​</a></h3><ul><li>刀刃武器：<strong>刀头 + 手柄</strong>分两条耐久</li><li>钝器更简单（无锐利度），但加固版（铁皮棒球棍）变重了</li></ul><h3 id="_3-锐利度" tabindex="-1">3. 锐利度 <a class="header-anchor" href="#_3-锐利度" aria-label="Permalink to &quot;3. 锐利度&quot;">​</a></h3><ul><li>刀刃武器会<strong>变钝</strong>，伤害下降</li><li>需要用磨石/锉刀/砂轮打磨</li><li><strong>武士刀不能磨</strong>（2025-02-10 B42 补丁）——坏了就没了</li></ul><h3 id="_4-修理衰减" tabindex="-1">4. 修理衰减 <a class="header-anchor" href="#_4-修理衰减" aria-label="Permalink to &quot;4. 修理衰减&quot;">​</a></h3><ul><li>后续修理效果递减：50% → 25% → 10%</li><li>维护技能现在有更大意义（修得更值）</li></ul><h3 id="_5-可制作武器" tabindex="-1">5. 可制作武器 <a class="header-anchor" href="#_5-可制作武器" aria-label="Permalink to &quot;5. 可制作武器&quot;">​</a></h3><ul><li>锻造线可制作刀剑和加固棒球棍</li><li>终局有了可持续的武器来源</li></ul><hr><h2 id="排名总览" tabindex="-1">排名总览 <a class="header-anchor" href="#排名总览" aria-label="Permalink to &quot;排名总览&quot;">​</a></h2><h3 id="s-档-—-顶级" tabindex="-1">S 档 — 顶级 <a class="header-anchor" href="#s-档-—-顶级" aria-label="Permalink to &quot;S 档 — 顶级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器</th><th>类型</th><th>重量</th><th>说明</th></tr></thead><tbody><tr><td>🥇 <strong>撬棍</strong></td><td>长棍</td><td>2.0</td><td><strong>耐久之王</strong>。能在你手上用到天荒地老。B42 修复了不给维护经验的问题，现在使用还能练维护。肌肉疲劳中等偏高但可接受</td></tr><tr><td>🥈 <strong>武士刀</strong></td><td>长刀</td><td>2.0</td><td>一击必杀率无可匹敌——但<strong>不能磨了</strong>。找到的是消耗品，不是永久伙伴。珍惜每一次挥砍</td></tr><tr><td>🥉 <strong>铁皮加固棒球棍</strong></td><td>长棍</td><td>较重</td><td>B42 新锻造终局武器。约 <strong>50% 暴击率</strong>，钝器之王。需要锻造投资</td></tr><tr><td>🏅 <strong>锻造剑</strong></td><td>长刀</td><td>中</td><td>可持续的武士刀替代品。金属加工 8-10 级制作。可再生终局武器</td></tr></tbody></table><h3 id="a-档-—-优秀" tabindex="-1">A 档 — 优秀 <a class="header-anchor" href="#a-档-—-优秀" aria-label="Permalink to &quot;A 档 — 优秀&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器</th><th>类型</th><th>重量</th><th>说明</th></tr></thead><tbody><tr><td><strong>砍刀</strong></td><td>长刀</td><td>1.5</td><td>伤害/速度平衡出色。~10 条耐久。胶带可修。30 天后更常见</td></tr><tr><td><strong>消防斧/伐木斧</strong></td><td>斧头</td><td>3.0</td><td>单发伤害极高。兼做砍树工具。<strong>重</strong>——肌肉疲劳来得很快</td></tr><tr><td><strong>园艺叉</strong></td><td>矛</td><td>1.5</td><td>高暴击 + 攻击距离优势。可附加刀刃升级</td></tr><tr><td><strong>猎刀</strong></td><td>短刀</td><td>0.5</td><td>极轻极快。B42 <strong>最小攻击距离缩小</strong>——近身可用。持续战斗能力最强</td></tr></tbody></table><h3 id="b-档-—-可靠日常" tabindex="-1">B 档 — 可靠日常 <a class="header-anchor" href="#b-档-—-可靠日常" aria-label="Permalink to &quot;B 档 — 可靠日常&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器</th><th>类型</th><th>重量</th><th>说明</th></tr></thead><tbody><tr><td><strong>警棍</strong></td><td>短棍</td><td>1.0</td><td>轻/快/耐久好——社区称为&quot;隐藏宝石&quot;，敏捷流的优质武器</td></tr><tr><td><strong>手斧</strong></td><td>单手斧</td><td>1.5</td><td>比双手斧轻，伤害仍可观。肌肉疲劳更友好</td></tr><tr><td><strong>钉刺棒球棍</strong></td><td>长棍</td><td>2.0</td><td>耐久中等（~15）。B42 中坏掉的钉子可以部分回收</td></tr><tr><td><strong>管钳</strong></td><td>短棍</td><td>1.5</td><td>单手棍类少有的高伤害选项</td></tr><tr><td><strong>手工矛+刀片</strong></td><td>矛</td><td>1.0</td><td>易量产、高暴击、攻击距离优势。绑定猎刀可大幅提升伤害</td></tr><tr><td><strong>铁管</strong></td><td>短棍</td><td>1.5</td><td>比管钳常见，入门级短棍首选</td></tr></tbody></table><h3 id="c-档-—-可用但有限制" tabindex="-1">C 档 — 可用但有限制 <a class="header-anchor" href="#c-档-—-可用但有限制" aria-label="Permalink to &quot;C 档 — 可用但有限制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>锤子</strong></td><td>短棍</td><td>常见但伤害低。早期可用，尽快升级</td></tr><tr><td><strong>平底锅</strong></td><td>短棍</td><td>比锤子稍好，仍然是入门级</td></tr><tr><td><strong>厨房刀</strong></td><td>短刀</td><td>极轻（肌肉疲劳几乎为零）但极度脆弱。已削弱的近身利器</td></tr><tr><td><strong>擀面杖</strong></td><td>短棍</td><td>常见但伤害极低。唯一优点：极轻</td></tr><tr><td><strong>木板</strong></td><td>短棍</td><td>遍地都是但耐久垃圾。紧急情况下最高 2 下就坏</td></tr></tbody></table><h3 id="d-档-—-特殊情况" tabindex="-1">D 档 — 特殊情况 <a class="header-anchor" href="#d-档-—-特殊情况" aria-label="Permalink to &quot;D 档 — 特殊情况&quot;">​</a></h3><table tabindex="0"><thead><tr><th>武器</th><th>说明</th></tr></thead><tbody><tr><td><strong>大锤</strong></td><td>破墙工具，不是战斗武器。肌肉疲劳来得极快，挥两下就虚了</td></tr><tr><td><strong>撬胎棒</strong></td><td>比管钳差，有更好的单手钝器就别用</td></tr><tr><td><strong>铅笔/钢笔</strong></td><td>搞笑武器，用来在多人模式羞辱朋友</td></tr></tbody></table><hr><h2 id="按玩法风格推荐" tabindex="-1">按玩法风格推荐 <a class="header-anchor" href="#按玩法风格推荐" aria-label="Permalink to &quot;按玩法风格推荐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风格</th><th>推荐主武器</th><th>副武器</th><th>原因</th></tr></thead><tbody><tr><td><strong>新手/长寿</strong></td><td>撬棍</td><td>警棍</td><td>最耐用+重量平衡。维护成本最低</td></tr><tr><td><strong>敏捷/风筝流</strong></td><td>猎刀</td><td>警棍</td><td>极轻续航+近身可用。肌肉疲劳几乎不存在</td></tr><tr><td><strong>猛男/战狂</strong></td><td>武士刀 → 锻造剑</td><td>消防斧</td><td>最大化单发伤害。接受肌肉疲劳</td></tr><tr><td><strong>制造者</strong></td><td>铁皮棒球棍</td><td>手工矛</td><td>锻造线投资回报。自给自足</td></tr><tr><td><strong>全能</strong></td><td>砍刀</td><td>手斧</td><td>伤害+工具+维护成本平衡</td></tr></tbody></table><hr><h2 id="武器类型的-b42-定位" tabindex="-1">武器类型的 B42 定位 <a class="header-anchor" href="#武器类型的-b42-定位" aria-label="Permalink to &quot;武器类型的 B42 定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>B41 地位</th><th>B42 地位</th><th>变化原因</th></tr></thead><tbody><tr><td><strong>长棍</strong></td><td>可靠</td><td>🔼 更可靠</td><td>撬棍 + 铁皮棒球棍终局</td></tr><tr><td><strong>长刀</strong></td><td>终极</td><td>🔽 不再绝对统治</td><td>武士刀不能磨，需锻造补位</td></tr><tr><td><strong>斧头</strong></td><td>主力</td><td>⚠ 续航变差</td><td>肌肉疲劳惩罚重武器</td></tr><tr><td><strong>短棍</strong></td><td>过渡</td><td>🔼 价值飞升</td><td>轻+快=更长战斗时间</td></tr><tr><td><strong>短刀</strong></td><td>垃圾</td><td>🔼 有了用武之地</td><td>极轻+近身可用</td></tr><tr><td><strong>矛</strong></td><td>自制专属</td><td>🔼 锻造联动</td><td>可附加锻造刀片升级</td></tr></tbody></table><hr><h2 id="武器修理策略-b42" tabindex="-1">武器修理策略 (B42) <a class="header-anchor" href="#武器修理策略-b42" aria-label="Permalink to &quot;武器修理策略 (B42)&quot;">​</a></h2><h3 id="修理优先级" tabindex="-1">修理优先级 <a class="header-anchor" href="#修理优先级" aria-label="Permalink to &quot;修理优先级&quot;">​</a></h3><ol><li><strong>撬棍等顶级耐久武器</strong>：50% 时就修（修理衰减在高质量武器上损失最小）</li><li><strong>锻造武器</strong>：用砂轮修——最安全，不会损伤武器</li><li><strong>不要用磨石/锉刀修锻造武器</strong>——可能造成额外损伤</li><li><strong>武士刀</strong>：用一次少一次，享受当下</li></ol><h3 id="修理工具" tabindex="-1">修理工具 <a class="header-anchor" href="#修理工具" aria-label="Permalink to &quot;修理工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>适用</th><th>风险</th></tr></thead><tbody><tr><td>磨石</td><td>刀刃武器</td><td>有几率损伤</td></tr><tr><td>锉刀</td><td>刀刃武器</td><td>有几率损伤</td></tr><tr><td>砂轮</td><td>刀刃武器</td><td>最安全</td></tr><tr><td>胶带</td><td>砍刀等</td><td>标准修理</td></tr><tr><td>木工胶</td><td>木质武器</td><td>标准修理</td></tr></tbody></table><hr><h2 id="初期过渡建议" tabindex="-1">初期过渡建议 <a class="header-anchor" href="#初期过渡建议" aria-label="Permalink to &quot;初期过渡建议&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一天：拿厨房能找到的平底锅/锤子/厨房刀</span></span>
<span class="line"><span>第一周：搜消防局/警局找消防斧/警棍/撬棍</span></span>
<span class="line"><span>第一个月：决定主修方向（锻造 for 剑/加固棍, 维护 for 保养）</span></span>
<span class="line"><span>终局：自给自足造武器，永远不缺</span></span></code></pre></div>`,42)])])}const u=d(e,[["render",n]]);export{c as __pageData,u as default};
